/**
 * dsh-session-temp-reaper — host half.
 *
 * One job: answer two questions about a session from the host side, because the
 * browser half cannot read files.
 *
 *  - `POST /session-temp-reaper/scan`   → which files did this session generate?
 *  - `POST /session-temp-reaper/delete` → remove the ones the user did not keep.
 *
 * Where "generated by this session" comes from:
 *
 *  1. The session log. `sessionQuery.readSession()` replays the complete event
 *     log. Two event shapes name a written path:
 *       - `tool/call` for `write`/`edit`, in the call's JSON `arguments`;
 *       - `tool/call` for a shell tool (`bash`, `pwsh`, `ops_bash`) whose
 *         command carries an explicit redirection or a file-writing verb
 *         (`>`, `>>`, `2>`, `tee`, `Out-File`, `Set-Content`, `New-Item`) —
 *         which is how a scratch script usually gets onto disk. A command that
 *         merely mentions a path in passing is not mined.
 *  2. The session's own spill directory under the OS temp root,
 *     `<tmp>/dsh-spill-<random>/session-<sessionId prefix>/`, which holds the
 *     tool output the harness spilled for THIS session.
 *
 * `bash` output is deliberately not mined: a shell command line is not a
 * reliable statement about which files it touched, and guessing here would
 * delete the wrong thing.
 *
 * Safety, in this order:
 *  - a target must appear in a scan produced by this plugin for that session;
 *  - a target must live inside the session cwd or inside that session's spill
 *    directory — nothing else is reachable, so no traversal and no host files;
 *  - anything under a `.git` directory is never listed and never deleted;
 *  - directories are deletable only when they are that session's spill
 *    directory, never a workspace directory;
 *  - the routes are same-origin only.
 *
 * Deleting is irreversible: the browser half shows the candidates and the user
 * unchecks what must stay before this route runs.
 */
import { createHash } from 'node:crypto';
import { existsSync, readFileSync } from 'node:fs';
import { open, readdir, realpath, rm, stat } from 'node:fs/promises';
import { createRequire } from 'node:module';
import { tmpdir } from 'node:os';
import { dirname, isAbsolute, join, normalize, relative, resolve, sep } from 'node:path';

export const name = 'session-temp-reaper';

/** Route prefix owned by this plugin; a composition-level contract. */
const ROUTE = '/api/session-temp-reaper';

/** Tool names whose arguments name one written path. */
const WRITE_TOOLS = new Set(['write', 'edit']);

/** Longest scan result kept per session, and how long it stays reusable. */
const SCAN_TTL_MS = 10 * 60 * 1000;

/** Scans by session id, so the delete route validates against what was offered. */
const scans = new Map();

/**
 * Upper bound on cached scans. The TTL alone only expires an entry when that
 * same session is visited again, so sessions that were scanned once and never
 * reopened would stay in memory for the lifetime of the process.
 */
const SCAN_MAX_ENTRIES = 64;

/** Drop expired entries, then the oldest ones past the cap. */
function trimScans() {
    const now = Date.now();
    for (const [id, record] of scans) {
        if (now - record.at > SCAN_TTL_MS) scans.delete(id);
    }
    while (scans.size > SCAN_MAX_ENTRIES) {
        const oldest = scans.keys().next().value;
        if (oldest === undefined) break;
        scans.delete(oldest);
    }
}

function validSessionId(value) {
    return typeof value === 'string' && value !== '' && value.length <= 200
        && /^[0-9A-Za-z_.:-]+$/.test(value);
}

function parseArguments(raw) {
    if (typeof raw !== 'string' || raw.trim() === '') return null;
    try {
        const parsed = JSON.parse(raw);
        return parsed !== null && typeof parsed === 'object' ? parsed : null;
    }
    catch {
        return null;
    }
}


/** True when `child` is `parent` itself or lives below it. */
function isInside(parent, child) {
    const rel = relative(parent, child);
    if (rel === '') return true;
    return rel !== '..' && !rel.startsWith('..' + sep) && !isAbsolute(rel);
}


function hasGitSegment(target) {
    return normalize(target).split(sep).includes('.git');
}

function displayPath(cwd, target) {
    const rel = relative(cwd, target);
    if (rel === '' || rel.startsWith('..')) return target;
    return rel.split(sep).join('/');
}

/**
 * Spill directory tokens the harness may have used for one session.
 *
 * Observed on disk: `<tmp>/dsh-spill-<random>/session-<12 hex>`, where the hex
 * is the first 12 characters of `sha256('session-' + sessionId)`. Both the
 * prefixed and the bare form are computed so a harness build that drops the
 * prefix still resolves, and a same-name directory is trusted by its path
 * alone rather than by re-deriving the hash.
 */
function spillTokens(sessionId) {
    const tokens = new Set();
    for (const base of [`session-${sessionId}`, sessionId]) {
        tokens.add(createHash('sha256').update(base).digest('hex').slice(0, 12));
    }
    return tokens;
}

/**
 * Session spill directories for one session under the OS temp root: every
 * `dsh-spill-<random>/session-<token>` whose token matches, plus anything the
 * current build derived another way (`session-<sessionId prefix>`).
 */
async function findSpillDirs(sessionId) {
    const root = tmpdir();
    let entries;
    try {
        entries = await readdir(root, { withFileTypes: true });
    }
    catch {
        return [];
    }
    const tokens = spillTokens(sessionId);
    const found = [];
    for (const entry of entries) {
        if (!entry.isDirectory() || !entry.name.startsWith('dsh-spill-')) continue;
        const spillRoot = join(root, entry.name);
        let children;
        try {
            children = await readdir(spillRoot, { withFileTypes: true });
        }
        catch {
            continue;
        }
        for (const child of children) {
            if (!child.isDirectory()) continue;
            const match = /^session-(.+)$/.exec(child.name);
            if (match === null) continue;
            const token = match[1];
            const known = tokens.has(token)
                || (token.length >= 8 && sessionId.startsWith(token))
                || (sessionId.length >= 8 && token.startsWith(sessionId));
            if (!known) continue;
            found.push(join(spillRoot, child.name));
        }
    }
    return found;
}

/**
 * Shell redirections and the file-writing verbs that name their target.
 * `cat > out.py <<'EOF'`, `cmd >> log.txt 2> err.txt`, `... | tee out.txt`,
 * `Set-Content -Path out.ps1`. Only explicit targets are mined: a command line
 * that merely mentions a path is not evidence that it wrote one.
 */
const REDIRECT_PATTERN = /(?:^|[\s;&|()])\d?>>?\s*(?:"([^"]*)"|'([^']*)'|([^\s;&|<>()"']+))/g;
const TEE_PATTERN = /(?:^|[\s;&|()])(?:tee|Out-File|Set-Content|Add-Content|New-Item)\s+(?:-(?:Path|FilePath|LiteralPath|append|Force|Value)\s+)*(?:"([^"]*)"|'([^']*)'|([^\s;&|<>()"']+))/gi;

/** Names a redirection uses for "throw it away", which are never candidates. */
const DISCARD_TARGETS = new Set(['/dev/null', 'nul', 'nul:']);

function looksDiscard(raw) {
    const value = raw.trim();
    if (value === '' || value === '-' || value.startsWith('&')) return true;
    if (value.includes('$') || value.includes('%')) return true; // unresolved variable
    return DISCARD_TARGETS.has(value) || DISCARD_TARGETS.has(value.toLowerCase());
}

/** Paths one shell command asks the system to write. */
function commandTargets(command) {
    const targets = [];
    for (const pattern of [REDIRECT_PATTERN, TEE_PATTERN]) {
        pattern.lastIndex = 0;
        let match;
        while ((match = pattern.exec(command)) !== null) {
            const raw = match[1] ?? match[2] ?? match[3];
            if (typeof raw !== 'string') continue;
            if (looksDiscard(raw)) continue;
            targets.push(raw);
        }
    }
    return targets;
}

/**
 * How far back "this session" reaches.
 *
 * A resumed Session keeps its whole log, including writes from weeks ago that
 * are not scratch anymore — they are the files that session delivered. Only the
 * recent tail of the log is considered, measured backwards from the newest
 * event, so the button talks about what happened around now.
 *
 * Widened from 24h to 72h: an item that is only context (unmarked) is never
 * deleted by default, so a longer window costs nothing but a longer list.
 */
const RECENT_WINDOW_MS = 72 * 60 * 60 * 1000;

/** Events inside the recent window; falls back to all events without times. */
function recentEvents(events) {
    let newest = 0;
    for (const event of events) {
        if (event === null || typeof event !== 'object' || typeof event.time !== 'number') continue;
        if (event.time > newest) newest = event.time;
    }
    if (newest === 0) return events;
    const cutoff = newest - RECENT_WINDOW_MS;
    return events.filter((event) => typeof event.time !== 'number' || event.time >= cutoff);
}

/**
 * Paths the model itself registered as temporary through `mark_temp_files`.
 * This is the authoritative definition of "temporary" for this session: the
 * tool call lives in the session log, so the marks replay with the log and are
 * visible to the user in the transcript.
 */
const MARK_TOOL = 'mark_temp_files';

function markedPaths(events, cwd) {
    const marked = new Map();
    for (const event of events) {
        if (event === null || typeof event !== 'object' || event.type !== 'tool/call') continue;
        const data = event.data;
        if (data === null || typeof data !== 'object' || data.name !== MARK_TOOL) continue;
        const args = parseArguments(data.arguments);
        if (args === null || !Array.isArray(args.paths)) continue;
        for (const raw of args.paths) {
            if (typeof raw !== 'string' || raw.trim() === '') continue;
            const absolute = normalize(isAbsolute(raw) ? raw : resolve(cwd, raw));
            if (hasGitSegment(absolute)) continue;
            marked.set(absolute, {
                source: 'marked',
                origin: typeof args.note === 'string' ? args.note.slice(0, 120) : '',
            });
        }
    }
    return marked;
}

/**
 * Paths the session explicitly handed to the user — a `present` tool call or a
 * deliverable record. Those are results, not scratch, whatever their age.
 */
function deliveredPaths(events, cwd) {
    const delivered = new Set();
    const offer = (raw) => {
        if (typeof raw !== 'string' || raw.trim() === '') return;
        const absolute = normalize(isAbsolute(raw) ? raw : resolve(cwd, raw));
        delivered.add(absolute);
    };
    for (const event of events) {
        if (event === null || typeof event !== 'object') continue;
        if (event.type === 'tool/call') {
            const data = event.data;
            if (data === null || typeof data !== 'object' || data.name !== 'present') continue;
            const args = parseArguments(data.arguments);
            if (args === null) continue;
            const files = Array.isArray(args.files) ? args.files : [];
            for (const file of files) {
                if (typeof file === 'string') offer(file);
                else if (file !== null && typeof file === 'object') offer(file.path ?? file.filePath ?? file.file_path);
            }
            continue;
        }
        if (typeof event.type === 'string' && event.type.includes('deliverable')) {
            const data = event.data;
            if (data === null || typeof data !== 'object') continue;
            for (const value of Object.values(data)) {
                if (typeof value === 'string') offer(value);
                else if (Array.isArray(value)) {
                    for (const item of value) {
                        if (typeof item === 'string') offer(item);
                        else if (item !== null && typeof item === 'object') offer(item.path ?? item.filePath);
                    }
                }
            }
        }
    }
    return delivered;
}

/**
 * How often this session touched each path, and whether any `edit` was among
 * the touches. A file that was edited — or written more than once — is being
 * maintained, not dumped as scratch: repeat-touched files are proposed for
 * keeping.
 */
function touchCounts(events, cwd) {
    const counts = new Map();
    for (const event of events) {
        if (event === null || typeof event !== 'object' || event.type !== 'tool/call') continue;
        const data = event.data;
        if (data === null || typeof data !== 'object' || !WRITE_TOOLS.has(data.name)) continue;
        const args = parseArguments(data.arguments);
        if (args === null) continue;
        const raw = args.path ?? args.file_path ?? args.filePath ?? args.target;
        if (typeof raw !== 'string' || raw.trim() === '') continue;
        const absolute = normalize(isAbsolute(raw) ? raw : resolve(cwd, raw));
        const current = counts.get(absolute) ?? { writes: 0, edits: 0 };
        if (data.name === 'edit') current.edits += 1;
        else current.writes += 1;
        counts.set(absolute, current);
    }
    return counts;
}

/**
 * Every path one session named as a write target, tagged with how it was named
 * and a short origin note so the user can tell what the file is:
 * a `write`/`edit` tool call, or a shell redirection in a `bash`, `pwsh` or
 * `ops_bash` command (which is how a scratch script usually appears).
 *
 * Paths outside the session cwd are returned too: the caller decides, and only
 * an explicit command target under the OS temp root survives that decision.
 */
function eventTargets(events, cwd) {
    const paths = new Map();
    const offer = (raw, source, origin) => {
        if (typeof raw !== 'string' || raw.trim() === '') return;
        const absolute = normalize(isAbsolute(raw) ? raw : resolve(cwd, raw));
        if (hasGitSegment(absolute)) return;
        // A write/edit call outranks a command mention for the same path.
        if (paths.get(absolute)?.source === 'session' && source !== 'session') return;
        paths.set(absolute, { source, origin });
    };
    for (const event of events) {
        if (event === null || typeof event !== 'object' || event.type !== 'tool/call') continue;
        const data = event.data;
        if (data === null || typeof data !== 'object') continue;
        const args = parseArguments(data.arguments);
        if (args === null) continue;
        if (WRITE_TOOLS.has(data.name)) {
            offer(
                args.path ?? args.file_path ?? args.filePath ?? args.target,
                'session',
                `${data.name} tool`,
            );
            continue;
        }
        if (typeof args.command === 'string') {
            const excerpt = args.command.replace(/\s+/g, ' ').trim().slice(0, 120);
            for (const target of commandTargets(args.command)) offer(target, 'command', excerpt);
        }
    }
    return paths;
}

/**
 * A short human label for what a file kind usually is, so a picker row can say
 * "config file" instead of only showing a name. Extension only: guessing from
 * content would misfire on generated code and data dumps alike.
 */
const KIND_BY_EXTENSION = new Map(Object.entries({
    config: 'json yml yaml toml ini conf cfg env properties lock',
    script: 'js mjs cjs ts tsx jsx py sh bash zsh ps1 bat cmd rb php lua pl',
    style: 'css scss less sass',
    markup: 'html htm vue svelte astro',
    doc: 'md markdown rst docx doc pdf rtf odt',
    sheet: 'xlsx xls csv tsv ods',
    slide: 'pptx ppt odp',
    image: 'png jpg jpeg gif webp svg bmp ico tif tiff avif',
    audio: 'mp3 wav ogg flac m4a aac',
    video: 'mp4 mov mkv webm avi',
    archive: 'zip 7z rar tar gz tgz bz2 xz',
    log: 'log',
    data: 'sql sqlite sqlite3 db parquet npy npz bin dat',
    text: 'txt text',
}).flatMap(([kind, list]) => list.split(' ').map((ext) => [ext, kind])));

function contentKind(target) {
    const dot = target.lastIndexOf('.');
    if (dot <= 0) return 'other';
    const ext = target.slice(dot + 1).toLowerCase();
    // `*.patch.yml` and friends: the last extension is what decides.
    return KIND_BY_EXTENSION.get(ext) ?? 'other';
}

/** Leading comment/bracket noise is stripped so the preview says something. */
const PREVIEW_NOISE = /^[\s{[\]}(),;:<>"'`=+|\\/-]+$/;
const PREVIEW_PREFIX = /^(?:\/\/+|#+|\/\*+|\*+|<!--|--+|;+|"+)\s*/;
const PREVIEW_SUFFIX = /\s*(?:\*\/|-->|"+)$/;
/** Decorative banner rules (`===== title =====`, `── title ──`) around a title. */
const PREVIEW_RULE_LEFT = /^[\s=#*~_+─═━-]{2,}/;
const PREVIEW_RULE_RIGHT = /[\s=#*~_+─═━-]{2,}$/;

/** A line worth showing: some words, not a bracket, not a banner rule. */
function looksMeaningful(line) {
    if (line === '' || PREVIEW_NOISE.test(line)) return false;
    if (/[\u4e00-\u9fff]/.test(line)) return true;
    return line.replace(/[^0-9A-Za-z]/g, '').length >= 4;
}

function meaningfulLine(text) {
    for (const rawLine of text.split(/\r?\n/)) {
        let line = rawLine.trim();
        if (line === '' || PREVIEW_NOISE.test(line)) continue;
        line = line.replace(PREVIEW_PREFIX, '').replace(PREVIEW_SUFFIX, '');
        line = line.replace(PREVIEW_RULE_LEFT, '').replace(PREVIEW_RULE_RIGHT, '').trim();
        if (!looksMeaningful(line)) continue;
        return line.slice(0, 160);
    }
    return '';
}

/** Top-level JSON keys, so a config file previews as "name, version, dsh". */
function jsonKeyPreview(text) {
    try {
        const parsed = JSON.parse(text);
        if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) return '';
        const keys = Object.keys(parsed);
        return keys.length === 0 ? '' : `keys: ${keys.slice(0, 6).join(', ')}${keys.length > 6 ? ' …' : ''}`;
    }
    catch {
        return '';
    }
}

/**
 * A one-line look at a file, for the picker's second row. Binary files (a NUL
 * byte in the head) get no preview — a mojibake snippet is worse than none —
 * and files that are gone by the time we read them get none either.
 */
async function readPreview(absolute) {
    let handle;
    try {
        handle = await open(absolute, 'r');
        const buffer = Buffer.alloc(4096);
        const { bytesRead } = await handle.read(buffer, 0, buffer.length, 0);
        if (bytesRead === 0) return { preview: '', binary: false };
        const head = buffer.subarray(0, bytesRead);
        if (head.includes(0)) return { preview: '', binary: true };
        const text = head.toString('utf8');
        const kind = contentKind(absolute);
        // Media and archives: the name and kind already say everything a
        // preview could, and their bytes would only print markup noise.
        if (kind === 'image' || kind === 'audio' || kind === 'video' || kind === 'archive') {
            return { preview: '', binary: false };
        }
        if (kind === 'config') {
            const keys = jsonKeyPreview(text);
            if (keys !== '') return { preview: keys, binary: false };
        }
        return { preview: meaningfulLine(text), binary: false };
    }
    catch {
        return { preview: '', binary: false };
    }
    finally {
        if (handle !== undefined) await handle.close().catch(() => {});
    }
}

/** Directories a workspace walk never enters: huge, generated, or VCS internals. */
const WALK_SKIP_DIRS = new Set([
    '.git', 'node_modules', '.venv', 'venv', '__pycache__', 'dist', 'build',
    'out', 'target', '.next', '.nuxt', '.cache', '.pnpm-store', 'coverage',
    '.gradle', '.idea', '.vs', 'bin', 'obj', '.tox', '.mypy_cache', '.pytest_cache',
]);

/** Bounds for the workspace walk; a big workspace must not stall the button. */
const WALK_MAX_FILES = 1500;
const WALK_MAX_ENTRIES = 20000;
const WALK_MAX_DEPTH = 12;

/**
 * Files created inside the workspace *by a command this session ran*, whatever
 * produced them. This is how a program's own output is caught: `python gen.py`
 * writes `out.tmp` without ever naming it on the command line.
 *
 * Attribution is intentionally strict, because "new since the session started"
 * is not the same as "this session's": another Session or a background plugin
 * writes into the same workspace, and the session's own `createdAt` can predate
 * its first command. A file is only listed when its creation time falls inside
 * the window that starts at one of THIS session's shell commands.
 */
const COMMAND_OUTPUT_WINDOW_MS = 15 * 60 * 1000;

/** Milliseconds timestamps of every shell command this session ran. */
function shellCommandTimes(events) {
    const times = [];
    for (const event of events) {
        if (event === null || typeof event !== 'object' || event.type !== 'tool/call') continue;
        const data = event.data;
        if (data === null || typeof data !== 'object') continue;
        const args = parseArguments(data.arguments);
        if (args === null || typeof args.command !== 'string' || args.command.trim() === '') continue;
        const time = typeof event.time === 'number' ? event.time : null;
        if (time !== null && Number.isFinite(time)) times.push(time);
    }
    return times;
}

/** True when `createdAt` falls in [command time, command time + window]. */
function insideCommandWindow(createdAt, commandTimes) {
    for (const time of commandTimes) {
        if (createdAt >= time && createdAt <= time + COMMAND_OUTPUT_WINDOW_MS) return true;
    }
    return false;
}

async function scanNewFiles(cwd, commandTimes) {
    const found = new Map();
    if (commandTimes.length === 0) return found;
    let visited = 0;
    // Breadth-first, so shallow files are found before a deep sibling tree can
    // spend the whole budget: `qq-bridge/...` must not starve `./out.tmp`.
    const queue = [[cwd, 0]];
    while (queue.length > 0 && found.size < WALK_MAX_FILES && visited < WALK_MAX_ENTRIES) {
        const [dir, depth] = queue.shift();
        let entries;
        try {
            entries = await readdir(dir, { withFileTypes: true });
        }
        catch {
            continue;
        }
        for (const entry of entries) {
            if (found.size >= WALK_MAX_FILES || visited >= WALK_MAX_ENTRIES) break;
            visited += 1;
            const absolute = join(dir, entry.name);
            if (entry.isDirectory()) {
                if (WALK_SKIP_DIRS.has(entry.name)) continue;
                if (depth + 1 > WALK_MAX_DEPTH) continue;
                queue.push([absolute, depth + 1]);
                continue;
            }
            if (!entry.isFile()) continue;
            let info;
            try {
                info = await stat(absolute);
            }
            catch {
                continue;
            }
            const created = typeof info.birthtimeMs === 'number' && info.birthtimeMs > 0
                ? info.birthtimeMs
                : info.mtimeMs;
            if (!insideCommandWindow(created, commandTimes)) continue;
            found.set(absolute, 'scan');
        }
    }
    return found;
}

/** Files sitting directly in the workspace root that appeared after this session
 * started, even when no command window covers them. A script the model wrote
 * itself is already an event target; this catches what a program created outside
 * every command window, which used to be dropped silently. Context only: the
 * `scan` source keeps it in the unmarked group, so it is proposed for keeping.
 *
 * @param cwd workspace root to list, non-recursively
 * @param since session header `createdAt` in ms; without it nothing is listed
 */
const ROOT_SCAN_MAX_FILES = 200;

async function recentRootFiles(cwd, since) {
    const found = new Map();
    if (typeof since !== 'number' || !Number.isFinite(since)) return found;
    let entries;
    try {
        entries = await readdir(cwd, { withFileTypes: true });
    }
    catch {
        return found;
    }
    for (const entry of entries) {
        if (found.size >= ROOT_SCAN_MAX_FILES) break;
        if (!entry.isFile()) continue;
        const absolute = join(cwd, entry.name);
        let info;
        try {
            info = await stat(absolute);
        }
        catch {
            continue;
        }
        const created = typeof info.birthtimeMs === 'number' && info.birthtimeMs > 0
            ? info.birthtimeMs
            : info.mtimeMs;
        if (created < since) continue;
        found.set(absolute, { source: 'scan', origin: '' });
    }
    return found;
}

/** True for anything inside a `dsh-spill-*` directory (another session's spills too). */
function isSpillPath(target) {
    return normalize(target).split(sep).some((segment) => segment.startsWith('dsh-spill-'));
}

/**
 * Explicit command targets outside the workspace: allowed only when the file
 * lives under the OS temp root, was created during this session, and is not
 * inside a spill directory (spills are listed as whole directories).
 */
async function externalTempFiles(cwd, targets, sessionStartedAt) {
    const found = new Map();
    if (typeof sessionStartedAt !== 'number' || !Number.isFinite(sessionStartedAt)) return found;
    const tempRoot = normalize(tmpdir());
    for (const [absolute, entry] of targets) {
        if (entry.source !== 'command') continue;
        if (isInside(cwd, absolute)) continue;
        if (!isInside(tempRoot, absolute)) continue;
        if (isSpillPath(absolute)) continue;
        let info;
        try {
            info = await stat(absolute);
        }
        catch {
            continue;
        }
        if (!info.isFile()) continue;
        const created = typeof info.birthtimeMs === 'number' && info.birthtimeMs > 0
            ? info.birthtimeMs
            : info.mtimeMs;
        if (created < sessionStartedAt) continue;
        found.set(absolute, { source: 'external', origin: entry.origin });
    }
    return found;
}

/**
 * Roots of every package this profile depends on.
 *
 * A session that authors a plugin writes that plugin's source into the
 * workspace, and the profile links straight to it — so those files are
 * session-created, non-deliverable by extension, and still the last thing that
 * should be deleted. Resolving the profile's dependency list to real paths is
 * what makes "referenced by the running profile" a fact rather than a guess.
 */
let referencedCache = { at: 0, roots: null };
const REFERENCED_TTL_MS = 60_000;

/** Walk up from a resolved entry file to the directory owning its package.json. */
function packageRootFrom(entryPath) {
    let dir = dirname(entryPath);
    for (let depth = 0; depth < 8; depth += 1) {
        try {
            const manifest = JSON.parse(readFileSync(join(dir, 'package.json'), 'utf8'));
            if (manifest !== null && typeof manifest.name === 'string') return dir;
        }
        catch {
            // No manifest here; keep climbing.
        }
        const parent = dirname(dir);
        if (parent === dir) break;
        dir = parent;
    }
    return null;
}

/**
 * The profile directory that owns the running dependency graph.
 *
 * `DSH_PROFILE_DIR` is set for profile-launched *shells*, not for the desktop
 * host process, so the launcher's arguments and working directory are the
 * reliable sources there. Candidates are tried in order and the first one with
 * a parseable `package.json` wins.
 */
function profileDirectories() {
    const candidates = [];
    if (typeof process.env.DSH_PROFILE_DIR === 'string' && process.env.DSH_PROFILE_DIR !== '') {
        candidates.push(process.env.DSH_PROFILE_DIR);
    }
    candidates.push(process.cwd());
    for (const arg of process.argv.slice(1)) {
        if (typeof arg === 'string' && arg !== '' && !arg.startsWith('-')) candidates.push(arg);
    }
    return [...new Set(candidates)];
}

function readProfileManifest() {
    for (const directory of profileDirectories()) {
        const manifestPath = join(directory, 'package.json');
        try {
            const manifest = JSON.parse(readFileSync(manifestPath, 'utf8'));
            if (manifest !== null && typeof manifest === 'object'
                && (manifest.dependencies !== undefined || manifest.devDependencies !== undefined)) {
                return { directory, manifestPath, manifest };
            }
        }
        catch {
            // Not a profile directory; try the next candidate.
        }
    }
    return null;
}

async function referencedPackageRoots() {
    const now = Date.now();
    if (now - referencedCache.at < REFERENCED_TTL_MS) return referencedCache.roots;
    const roots = new Set();
    const found = readProfileManifest();
    // No discoverable profile manifest means "cannot tell", not "nothing is
    // referenced": returning an empty list would silently drop the protection
    // and make the panel claim every file is safe to delete.
    if (found === null) {
        referencedCache = { at: now, roots: null };
        return null;
    }
    const names = new Set([
        ...Object.keys(found.manifest.dependencies ?? {}),
        ...Object.keys(found.manifest.devDependencies ?? {}),
    ]);
    let requireFrom = null;
    try {
        requireFrom = createRequire(found.manifestPath);
    }
    catch {
        requireFrom = null;
    }
    for (const name of names) {
        if (requireFrom === null) break;
        let entry = null;
        for (const attempt of [`${name}/package.json`, name]) {
            try {
                entry = requireFrom.resolve(attempt);
                break;
            }
            catch {
                // Exported subpaths may hide package.json; try the bare name.
            }
        }
        if (entry === null) continue;
        const root = normalize(packageRootFrom(entry) ?? dirname(entry));
        try {
            roots.add(normalize(await realpath(root)));
        }
        catch {
            roots.add(root);
        }
    }
    referencedCache = { at: now, roots: [...roots] };
    return referencedCache.roots;
}


/**
 * @param sessionStartedAt session header `createdAt` in ms. A file older than
 * the session that a command merely redirected into is almost certainly an
 * existing file, not scratch, so it is proposed for keeping.
 */
async function listFiles(cwd, paths, sessionStartedAt, referencedRoots, delivered, touches) {
    const files = [];
    for (const [absolute, entry] of paths) {
        let info;
        try {
            info = await stat(absolute);
        }
        catch {
            // Already gone, or never created: nothing to offer.
            continue;
        }
        if (!info.isFile()) continue;
        // Creation time, not mtime: appending to an old file updates mtime, so
        // mtime alone cannot tell "this session created it" from "this session
        // touched a file that was already here".
        const created = typeof info.birthtimeMs === 'number' && info.birthtimeMs > 0
            ? info.birthtimeMs
            : info.mtimeMs;
        const { preview, binary } = await readPreview(absolute);
        // Linked into the running profile: deleting it breaks a plugin or a
        // dependency, so it is protected even when marked. `null` roots mean
        // the profile could not be located, which is reported as 'unknown'
        // rather than as "not referenced".
        const referenced = referencedRoots === null
            ? 'unknown'
            : referencedRoots.some((root) => isInside(root, absolute));
        const unattributed = entry.source === 'scan';
        // Explicitly handed to the user: a result, never scratch.
        const isDelivered = delivered.has(absolute);
        // Edited, or written more than once: maintained, not dumped scratch.
        const touches_ = touches.get(absolute);
        const maintained = touches_ !== undefined && (touches_.edits > 0 || touches_.writes + touches_.edits > 1);
        const marked = entry.source === 'marked';
        files.push({
            path: absolute,
            display: displayPath(cwd, absolute),
            kind: 'file',
            type: contentKind(absolute),
            source: entry.source,
            origin: entry.origin ?? '',
            size: info.size,
            mtime: info.mtimeMs,
            createdAt: created,
            preview,
            binary,
            referenced,
            unattributed,
            delivered: isDelivered,
            maintained,
            marked,
            // The model's own mark is the definition of "temporary": those are
            // proposed for deletion, with delivered/profile-referenced files
            // still protected. Everything the model did NOT mark is only
            // context for the user and is proposed for keeping.
            // The model's own mark is the definition of "temporary": those are
            // proposed for deletion, with delivered/profile-referenced files
            // still protected. Everything the model did NOT mark is only
            // context for the user and is proposed for keeping.
            keepByDefault: marked
                ? (isDelivered || referenced === true)
                : true,
        });
    }
    return files;
}

async function listSpill(sessionId) {
    const dirs = [];
    for (const dir of await findSpillDirs(sessionId)) {
        let info;
        try {
            info = await stat(dir);
        }
        catch {
            continue;
        }
        if (!info.isDirectory()) continue;
        dirs.push({
            path: dir,
            display: dir,
            kind: 'dir',
            type: 'dir',
            source: 'spill',
            size: 0,
            mtime: info.mtimeMs,
            // The harness own spill directory for this session is temporary by
            // definition, so it joins the marked group instead of the context one.
            marked: true,
            keepByDefault: false,
        });
    }
    return dirs;
}

/** Build the candidate list for one session and remember it for the delete call. */
async function scan(sessionQuery, sessionId) {
    const snapshot = await sessionQuery.readSession(sessionId);
    const cwd = normalize(snapshot.session?.cwd ?? process.cwd());
    const startedAt = snapshot.session?.createdAt;
    const allEvents = snapshot.events ?? [];
    // Marks come from the whole log: the model may have marked a file hours ago.
    // They outrank every heuristic below.
    const marks = markedPaths(allEvents, cwd);
    const paths = new Map();
    for (const [absolute, entry] of marks) {
        if (isInside(cwd, absolute)) paths.set(absolute, entry);
    }
    // Candidate discovery stays on the recent tail, but the protection state
    // must be read from the whole log: a `present` from days ago still means
    // "delivered", and a file edited long ago is still maintained. Reading
    // those from the window let an old deliverable lose its protection as soon
    // as the session logged anything newer.
    const events = recentEvents(allEvents);
    const targets = eventTargets(events, cwd);
    for (const [absolute, entry] of targets) {
        if (isInside(cwd, absolute) && !paths.has(absolute)) paths.set(absolute, entry);
    }
    // Files that appeared inside one of this session's command windows: a
    // program's own output. Nothing else is attributed to the session.
    const commandTimes = shellCommandTimes(events);
    if (commandTimes.length > 0) {
        for (const absolute of (await scanNewFiles(cwd, commandTimes)).keys()) {
            if (!paths.has(absolute)) paths.set(absolute, { source: 'scan', origin: '' });
        }
    }
    // Root-level files that appeared after the session started but matched no
    // command window. Shown as context (unmarked group), never default-selected.
    for (const [absolute, entry] of await recentRootFiles(cwd, startedAt)) {
        if (!paths.has(absolute)) paths.set(absolute, entry);
    }
    // Explicit command targets under the OS temp root.
    for (const [absolute, entry] of await externalTempFiles(cwd, targets, startedAt)) {
        if (!paths.has(absolute)) paths.set(absolute, entry);
    }
    const referencedRoots = await referencedPackageRoots();
    const files = await listFiles(
        cwd,
        paths,
        startedAt,
        referencedRoots,
        deliveredPaths(allEvents, cwd),
        touchCounts(allEvents, cwd),
    );
    const spill = await listSpill(sessionId);
    const items = [...files, ...spill].sort((a, b) => a.display.localeCompare(b.display));
    // `profileKnown: false` means the profile could not be located, so the
    // dependency protection could not be evaluated. The panel says so out loud
    // instead of pretending every listed file is unreferenced.
    const record = { at: Date.now(), cwd, items, profileKnown: referencedRoots !== null };
    scans.set(sessionId, record);
    trimScans();
    return record;
}

/**
 * The session's working directory, for validating `mark_temp_files` arguments.
 * Cached briefly because the marker tool runs on every mark call, while the
 * cwd only changes when a session is forked into another workspace.
 */
const sessionCwdCache = new Map();
const SESSION_CWD_TTL_MS = 5 * 60 * 1000;

/** Same bound and eviction order as `scans`, for the same reason. */
const SESSION_CWD_MAX_ENTRIES = 64;

/** Drop expired entries, then the oldest ones past the cap. */
function trimSessionCwdCache() {
    const now = Date.now();
    for (const [id, record] of sessionCwdCache) {
        if (now - record.at > SESSION_CWD_TTL_MS) sessionCwdCache.delete(id);
    }
    while (sessionCwdCache.size > SESSION_CWD_MAX_ENTRIES) {
        const oldest = sessionCwdCache.keys().next().value;
        if (oldest === undefined) break;
        sessionCwdCache.delete(oldest);
    }
}

async function sessionCwdFor(sessionQuery, sessionId) {
    if (typeof sessionId !== 'string' || sessionId === '') return null;
    const cached = sessionCwdCache.get(sessionId);
    if (cached !== undefined && Date.now() - cached.at < SESSION_CWD_TTL_MS) {
        // Refresh insertion order so the LRU trim keeps the sessions in use.
        sessionCwdCache.delete(sessionId);
        sessionCwdCache.set(sessionId, cached);
        return cached.cwd;
    }
    let cwd = null;
    try {
        const snapshot = await sessionQuery.readSession(sessionId);
        const raw = snapshot?.session?.cwd;
        cwd = typeof raw === 'string' && raw !== '' ? normalize(raw) : null;
    }
    catch {
        // Unknown session: the tool keeps its previous permissive behaviour
        // rather than refusing every mark.
        cwd = null;
    }
    // Re-insert so the LRU trim keeps the sessions in use.
    sessionCwdCache.delete(sessionId);
    sessionCwdCache.set(sessionId, { at: Date.now(), cwd });
    trimSessionCwdCache();
    return cwd;
}

function cachedScan(sessionId) {
    const record = scans.get(sessionId);
    if (record === undefined) return null;
    if (Date.now() - record.at > SCAN_TTL_MS) {
        scans.delete(sessionId);
        return null;
    }
    // Refresh insertion order so the LRU trim keeps recently used scans.
    scans.delete(sessionId);
    scans.set(sessionId, record);
    return record;
}

/**
 * Remove requested paths, keeping only ones this plugin offered for that
 * session. Returns one entry per requested path.
 */
async function removeFiles(sessionQuery, sessionId, requested) {
    let record = cachedScan(sessionId);
    if (record === null) record = await scan(sessionQuery, sessionId);
    const offered = new Map(record.items.map((item) => [item.path, item]));
    const spillDirs = new Set(record.items.filter((item) => item.source === 'spill').map((item) => item.path));
    const results = [];
    let removed = 0;
    for (const raw of requested) {
        if (typeof raw !== 'string' || raw === '') continue;
        const absolute = normalize(raw);
        const item = offered.get(absolute);
        if (item === undefined) {
            results.push({ path: absolute, ok: false, code: 'not-offered' });
            continue;
        }
        // Delivered and in-use files are refused by the host, not merely
        // unticked by the client: `keepByDefault` is a UI default, and a
        // request can arrive with every path selected.
        if (item.delivered === true || item.referenced === true) {
            results.push({ path: absolute, ok: false, code: 'protected' });
            continue;
        }
        // The scan is the allowlist. Beyond it, the only reachable places are
        // the session cwd, that session's spill directory, and a temp-root file
        // this scan classified as an explicit command target.
        const tempRoot = normalize(tmpdir());
        const reachable = isInside(record.cwd, absolute)
            || spillDirs.has(absolute)
            || (item.source === 'external' && isInside(tempRoot, absolute) && !isSpillPath(absolute));
        if (!reachable) {
            results.push({ path: absolute, ok: false, code: 'outside' });
            continue;
        }
        if (hasGitSegment(absolute)) {
            results.push({ path: absolute, ok: false, code: 'git' });
            continue;
        }
        try {
            if (item.kind === 'dir') {
                if (!spillDirs.has(absolute)) {
                    results.push({ path: absolute, ok: false, code: 'not-a-spill-dir' });
                    continue;
                }
                await rm(absolute, { recursive: true, force: false });
            }
            else {
                await rm(absolute, { force: false });
            }
            removed += 1;
            results.push({ path: absolute, ok: true });
        }
        catch (error) {
            const code = error?.code === 'ENOENT' ? 'missing' : 'rm';
            results.push({ path: absolute, ok: false, code, error: String(error?.message ?? error) });
        }
    }
    if (removed > 0) scans.delete(sessionId);
    return { results, removed };
}

/** Requests are small JSON envelopes; anything bigger is a mistake or an attack. */
const MAX_BODY_CHARS = 1_000_000;

/**
 * Read a bounded JSON body. The bridge already buffered the raw request, so the
 * only thing to protect here is this second copy: read chunk by chunk and stop
 * at the cap instead of turning an unbounded body into one giant string.
 */
async function readJson(request) {
    const declared = Number.parseInt(request.headers.get('content-length') ?? '', 10);
    if (Number.isFinite(declared) && declared > MAX_BODY_CHARS) {
        throw new Error('request body too large');
    }
    if (request.body === null) return {};
    const reader = request.body.getReader();
    const decoder = new TextDecoder();
    let text = '';
    try {
        for (;;) {
            const { done, value } = await reader.read();
            if (done) break;
            text += decoder.decode(value, { stream: true });
            if (text.length > MAX_BODY_CHARS) {
                await reader.cancel().catch(() => {});
                throw new Error('request body too large');
            }
        }
    }
    finally {
        reader.releaseLock();
    }
    text += decoder.decode();
    if (text === '') return {};
    return JSON.parse(text);
}

function jsonResponse(status, body) {
    return new Response(JSON.stringify(body), {
        status,
        headers: {
            'content-type': 'application/json; charset=utf-8',
            'cache-control': 'no-store',
        },
    });
}

/**
 * Register the two routes as exact Fetch routes on DSH's authenticated `/api`
 * channel. The bridge checks Host/Origin and the browser or API credential
 * before any byte is read, and only an owner Peer reaches the handler, so this
 * plugin carries no authentication of its own. Registration fails loudly if the
 * channel rejects a path, which is better than silently serving an open route.
 */
export function apply(ctx) {
    ctx.inject(['connection', 'sessionQuery'], (host) => {
        host.effect(() => {
            const route = (path, handle) => host.connection.fetch.register({
                path,
                methods: ['POST'],
                requestBody: 'buffered',
                fetch: async (request) => {
                    if (request.method !== 'POST') {
                        return new Response(null, { status: 405, headers: { allow: 'POST' } });
                    }
                    let body;
                    try {
                        body = await readJson(request);
                    }
                    catch (error) {
                        return jsonResponse(400, { ok: false, code: 'bad-request', error: String(error?.message ?? error) });
                    }
                    const sessionId = body?.sessionId;
                    if (!validSessionId(sessionId)) {
                        return jsonResponse(400, { ok: false, code: 'invalid-session' });
                    }
                    try {
                        const result = await handle(sessionId, body);
                        return jsonResponse(200, { ok: true, ...result });
                    }
                    catch (error) {
                        return jsonResponse(500, {
                            ok: false,
                            code: 'scan-failed',
                            error: String(error?.message ?? error),
                        });
                    }
                },
            });
            const disposers = [
                route(`${ROUTE}/scan`, async (sessionId) => {
                    const record = await scan(host.sessionQuery, sessionId);
                    return { cwd: record.cwd, items: record.items, profileKnown: record.profileKnown !== false };
                }),
                route(`${ROUTE}/delete`, async (sessionId, body) => {
                    const requested = Array.isArray(body?.paths) ? body.paths : [];
                    if (requested.length === 0) return { results: [], removed: 0 };
                    return removeFiles(host.sessionQuery, sessionId, requested);
                }),
            ];
            return () => {
                scans.clear();
                sessionCwdCache.clear();
                for (const dispose of disposers) void dispose();
            };
        }, 'session-temp-reaper: api routes');
    });

    // The model defines "temporary" for this session by calling the marker; the
    // call itself is a normal tool call, so the marks replay with the session log
    // and show up in the transcript.
    ctx.inject(['tools', 'sessionQuery'], (toolHost) => {
        toolHost.effect(() => toolHost.tools.register({
            name: MARK_TOOL,
            description: 'Mark files created during this session that are temporary or intermediate '
                + '(scratch scripts, test files, logs, caches, one-off outputs), so the user can review '
                + 'and delete them from the composer cleanup button. Do not mark deliverables, files the '
                + 'user asked to keep, or existing source files you edited.',
            parameters: {
                type: 'object',
                properties: {
                    paths: {
                        type: 'array',
                        items: { type: 'string' },
                        description: 'Paths, absolute or relative to the session working directory.',
                    },
                    note: {
                        type: 'string',
                        description: 'Optional short note on what these files are for.',
                    },
                },
                required: ['paths'],
                additionalProperties: false,
            },
            output: {
                schema: {
                    type: 'object',
                    properties: {
                        marked: { type: 'array', items: { type: 'string' } },
                        ignored: {
                            type: 'array',
                            items: {
                                type: 'object',
                                properties: {
                                    path: { type: 'string' },
                                    reason: { type: 'string' },
                                },
                                required: ['path', 'reason'],
                                additionalProperties: false,
                            },
                        },
                    },
                    required: ['marked', 'ignored'],
                    additionalProperties: false,
                },
                render: (args, value) => [{
                    type: 'text',
                    text: value.ignored.length === 0
                        ? `Marked ${value.marked.length} temporary file(s).`
                        : `Marked ${value.marked.length} temporary file(s), ignored ${value.ignored.length}.`,
                }],
            },
            execute: async (args, exec) => {
                const requested = Array.isArray(args?.paths) ? args.paths : [];
                // The panel only lists paths inside the session working directory,
                // so a mark outside it would never appear there. Refuse it here,
                // with a reason the model can act on, instead of accepting it and
                // dropping it silently during the scan.
                const cwd = await sessionCwdFor(toolHost.sessionQuery, exec?.agent?.id);
                const marked = [];
                const ignored = [];
                for (const raw of requested) {
                    if (typeof raw !== 'string' || raw.trim() === '') {
                        ignored.push({ path: typeof raw === 'string' ? raw : String(raw), reason: 'empty' });
                        continue;
                    }
                    const path = raw.trim();
                    if (hasGitSegment(path)) {
                        ignored.push({ path, reason: 'git' });
                        continue;
                    }
                    if (cwd !== null) {
                        const absolute = normalize(isAbsolute(path) ? path : resolve(cwd, path));
                        if (!isInside(cwd, absolute)) {
                            ignored.push({ path, reason: 'outside-cwd' });
                            continue;
                        }
                    }
                    marked.push(path);
                }
                return { marked, ignored };
            },
        }), 'session-temp-reaper: mark tool');
    });

    ctx.inject(['systemPrompt'], (promptHost) => {
        promptHost.effect(() => promptHost.systemPrompt.section({
            name: 'session-temp-reaper',
            order: 900,
            text: '## Temporary files\n'
                + 'Whenever you create a temporary or intermediate artifact (a scratch script, a test file, '
                + 'a log, a cache, a one-off output), call `mark_temp_files` with its path(s) right away. '
                + 'Do not mark deliverables, files the user asked to keep, or existing source files you '
                + 'edited. The user can review and delete the marked files from the cleanup button beside '
                + 'the composer; unmarked files are not offered for deletion by default.\n',
        }), 'session-temp-reaper: prompt section');
    });
}
